from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
out = []
for w in mw.findChildren(QAction):
    if w.text() == 'Copy':
        info = {'enabled': w.isEnabled(), 'visible': w.isVisible(), 'shortcut': w.shortcut().toString(), 'parent': '%s(%s)' % (w.parent().metaObject().className() if w.parent() else '?', w.parent().objectName() if w.parent() else '')}
        parents = []
        for obj in w.associatedObjects():
            if obj.isWidgetType():
                chain = []
                p = obj
                while p is not None:
                    chain.append('%s(%s)' % (p.metaObject().className(), p.objectName()))
                    p = p.parentWidget()
                parents.append(' <- '.join(chain[:8]))
        info['associated'] = parents
        out.append(info)
result = out
"}

